// === Inspired by 'Packedii' by 'Rubén Medellín &lt;chubas&gt;' ===
// Created as variant #3 by Uncler M
// Infused with creative algorithmic modifications.

// For the #WCCChallenge «Tangram» (join the discord! https://discord.gg/S8c7qcjw2b)
//
// Packed circles with some added rotation. Packing is almost filling the canvas right? (it almost follows the theme)
//
// The circles check collisions with others, but they can be inside other circles. When this happens, they are linked to their parent circle, forming a tree structure.
// For drawing them, the parent circle is drawn first, then a rotation is applied, and the children are drawn recursively
// Add some blob noise for the circles to not be perfect, and add some filters on top of it

let circles = []
let minDistance = 2
let minRadius = 10
let initialStartRadius = 300
let currentStartRadius
let radiusDecayRate = 2
let growthRate = 2
let newSeedInterval = 2
let seedsPerBatch = 1
let maxRetries = 50
let maxConsecutiveFailures = 100
let consecutiveFailures = 0
let stoppedAddingSeeds = false
let initialSeeds = 5
let palettes = [
  ["#fb6107","#f3de2c","#7cb518","#5c8001","#fbb02d"],
  ["#f72585","#7209b7","#b6f500","#000000","#ffffff"],
  ["#094074","#3c6997","#5adbff","#ffdd4a","#fe9000"],
  ["#05668d","#028090","#00a896","#f0f3bd"],
  ["#3c1642","#086375","#1dd3b0","#affc41","#b2ff9e"],
  ["#e5c679","#000807","#357266","#ed6a5e","#4ce0b3","#cfa5b4","#eae8ff","#b0d7ff","#61f2c2"],
  ["#3d2d1c","#30633d","#123c69","#1d58ab","#72c0ed","#fdefc0","#ffdf7c","#feb640","#d97b38","#a46379"],
  ["#080f0f","#2c4a73","#426c85","#4e6baa","#5c59c9","#c33b1e","#f07d23","#ffcc33","#fff1a1","#f1f5f8"],
  ["#fffcf2","#ccc5b9","#403d39","#252422","#eb5e28"],
  ["#faeee0","#fec802","#f69f40","#bf5f07","#0dc9c5","#18761a"],
  ["#0a122a","#771918","#3c5a14","#ffbb33","#a53e12"],
  ["#1a535c","#4ecdc4","#f7fff7","#ff6b6b","#ffe66d"],
  ["#283d3b","#197278","#edddd4","#c44536","#772e25"],
  ["#fb6107","#f3de2c","#7cb518","#5c8001","#fbb02d"],
	["#03045e","#023e8a","#0077b6","#0096c7","#00b4d8","#48cae4","#90e0ef","#ade8f4","#caf0f8"]
]
let palette, bgColor
let rotationMode
let dotFilter, bloomFilter

function setup() {
  createCanvas(windowWidth, windowHeight)
	pixelDensity(1)

	palette = random(palettes)
	rotationMode = random(["alternating", "same", "random", "noise"])
	bgColor = random(palette)
	bgColor = chroma(bgColor).desaturate(0.5).brighten(0.5).hex()

	dotFilter = createFilterShader(dotFilterShader)
	dotFilter.setUniform("u_resolution", [width, height]);
	dotFilter.setUniform("dotSizePx", [8, 8]);
	dotFilter.setUniform("dotStrength", 0.15);
	dotFilter.setUniform("u_skipColor", hexToRgb01(bgColor));
	dotFilter.setUniform("u_skipTolerance", 0.06);

	bloomFilter = createFilterShader(bloomFilterShader)
	bloomFilter.setUniform("intensity", 0.5);
	bloomFilter.setUniform("glow", 1.5);

  currentStartRadius = initialStartRadius

  for (let i = 0; i < initialSeeds; i++) {
    addSeed()
  }
}

function draw() {
  // === Variant 3: Fractal Orbit Matrix ===
  gridOffset = noise(frameCount * 0.01) * 80;
  push();
  translate(gridOffset, -gridOffset);

  background(bgColor)

  if (currentStartRadius > minRadius) {
    currentStartRadius = max(minRadius, currentStartRadius - radiusDecayRate)
  }

  for (let c of circles) {
    if (c.active) {
      growCircle(c)
    }
  }

  updateRotations()

  if (!stoppedAddingSeeds && frameCount % newSeedInterval === 0) {
    for (let i = 0; i < seedsPerBatch; i++) {
      let success = addSeed()
      if (success) {
        consecutiveFailures = 0
      } else {
        consecutiveFailures++
        if (consecutiveFailures >= maxConsecutiveFailures) {
          stoppedAddingSeeds = true
          break
        }
      }
    }
  }

  for (let c of circles) {
    if (c.parent === null) {
      drawCircleRecursive(c)
    }
  }
	filter(dotFilter)
	filter(bloomFilter)

  pop();
}

function growCircle(c) {
  if (
    c.x - c.radius <= 0 ||
    c.x + c.radius >= width ||
    c.y - c.radius <= 0 ||
    c.y + c.radius >= height
  ) {
    c.active = false
    assignColor(c)
    return
  }

  let newRadius = c.radius + growthRate

  for (let other of circles) {
    if (other === c) continue

    let d = dist(c.x, c.y, other.x, other.y)

    if (!isValidCircleDistance(newRadius, other.radius, d)) {
      c.active = false
      assignColor(c)
      return
    }
  }

  c.radius = newRadius
}

function assignColor(c) {
  let touchingColors = new Set()
  for (let other of circles) {
    if (other === c || !other.color) continue

    let d = dist(c.x, c.y, other.x, other.y)
    let gap = getCircleGap(c.radius, other.radius, d)

    if (abs(gap - minDistance) < 1) {
      touchingColors.add(other.color)
    }
  }

  if (c.parent && c.parent.color) {
    touchingColors.add(c.parent.color)
  }

  let availableColors = palette.filter((color) => !touchingColors.has(color))

  if (availableColors.length > 0) {
    c.color = random(availableColors)
  } else {
    c.color = random(palette)
  }
	let opacity = round(map(c.layer, 0, 6, 255, 160, true))
	let opacityHex = opacity.toString(16).padStart(2, "0")
	c.color = c.color + opacityHex
}

function getCircleGap(r1, r2, d) {
  let rLarge = max(r1, r2)
  let rSmall = min(r1, r2)

  if (d + rSmall < rLarge) {
    return rLarge - d - rSmall
  } else if (d >= rLarge + rSmall) {
    return d - rLarge - rSmall
  } else {
    return 0
  }
}

function isValidCircleDistance(r1, r2, d) {
  let rLarge = max(r1, r2)
  let rSmall = min(r1, r2)

  if (d + rSmall < rLarge) {
    let gap = rLarge - d - rSmall
    return gap >= minDistance
  } else if (d >= rLarge + rSmall) {
    let gap = d - rLarge - rSmall
    return gap >= minDistance
  } else {
    return false
  }
}

function addSeed() {
  let retries = 0
  let validPosition = false
  let x, y

  let minX = currentStartRadius
  let maxX = width - currentStartRadius
  let minY = currentStartRadius
  let maxY = height - currentStartRadius

  if (maxX < minX || maxY < minY) {
    return false
  }

  while (retries < maxRetries && !validPosition) {
    x = random(minX, maxX)
    y = random(minY, maxY)

    validPosition = true
    for (let c of circles) {
      let d = dist(x, y, c.x, c.y)

      if (!isValidCircleDistance(currentStartRadius, c.radius, d)) {
        validPosition = false
        break
      }
    }

    retries++
  }

  if (validPosition) {
    let layerInfo = calculateLayer(x, y, currentStartRadius)
    let circleBaseSpeed = random(0.05, 0.3)
    let rotationSpeed = calculateRotationSpeed(layerInfo.layer, x, y, circleBaseSpeed)

    let newCircle = {
      x: x,
      y: y,
      radius: currentStartRadius,
      active: true,
      color: null,
      layer: layerInfo.layer,
      parent: layerInfo.parent,
      children: [],
      rotationAngle: 0,
      rotationSpeed: rotationSpeed,
      baseRotationSpeed: circleBaseSpeed,
			seed: random(1000),
			hachureAngle: random(0, 360),
			hachureGap: random(3, 5),
    }

    if (layerInfo.parent) {
      layerInfo.parent.children.push(newCircle)
    }

    circles.push(newCircle)
    return true
  }

  return false
}

function calculateLayer(x, y, radius) {
  let maxLayer = -1
  let parent = null

  for (let c of circles) {
    let d = dist(x, y, c.x, c.y)

    if (d + radius < c.radius) {
      if (c.layer > maxLayer) {
        maxLayer = c.layer
        parent = c
      }
    }
  }

  return {
    layer: maxLayer + 1,
    parent: parent,
  }
}

function calculateRotationSpeed(layer, x, y, circleBaseSpeed) {
  let speedMultiplier = (10 - layer) / 3
  let direction

  switch (rotationMode) {
    case "alternating":
      direction = layer % 2 === 0 ? 1 : -1
      break

    case "same":
      direction = 1
      break

    case "random":
      direction = random() > 0.5 ? 1 : -1
      break

    case "noise":
      direction = noise(x * 0.01, y * 0.01) > 0.5 ? 1 : -1
      break

    default:
      direction = layer % 2 === 0 ? 1 : -1
  }

  return circleBaseSpeed * speedMultiplier * direction
}

function updateRotations() {
  for (let c of circles) {
    if (c.children.length > 0) {
      c.rotationAngle += c.rotationSpeed
    }
  }
}

function drawCircleRecursive(c, parent = null) {
	let tx = parent ? c.x - parent.x : c.x
	let ty = parent ? c.y - parent.y : c.y
	push()
	translate(tx, ty)

  rotate(radians(c.rotationAngle))

  if (c.color) {
    fill(c.color)
  } else {
    noFill()
  }

	noStroke()

	drawCircle(c)

  for (let child of c.children) {
		drawCircleRecursive(child, c)
  }

  pop()
}

function drawCircle(c) {
	let numAngles = 10
	beginShape()
	for (let i = 0; i < numAngles; i++) {
		let angle = i * TAU / numAngles + map(noise(i, c.x, c.y), 0, 1, -0.1, 0.1)
		let x = c.radius * cos(angle) + map(noise(c.x, c.y, angle), 0, 1, -5, 5)
		let y = c.radius * sin(angle) + map(noise(c.x, c.y, angle), 0, 1, -5, 5)
		splineVertex(x, y)
	}
	endShape(CLOSE)
}

function hexToRgb01(hex) {
  const h = hex.replace('#','');
  const r = parseInt(h.slice(0,2), 16) / 255;
  const g = parseInt(h.slice(2,4), 16) / 255;
  const b = parseInt(h.slice(4,6), 16) / 255;
  return [r,g,b];
}

let dotFilterShader = `
precision highp float;

varying vec2 vTexCoord;
uniform sampler2D tex0;

uniform vec2 u_resolution;
uniform vec2 dotSizePx;        // dot size in pixels (x,y)
uniform float dotStrength;     // 0..1

uniform vec3 u_skipColor;      // background color to preserve (0..1 RGB)
uniform float u_skipTolerance; // e.g. 0.02..0.12 (depends on your palette)

float colorDist(vec3 a, vec3 b) {
  // Euclidean in RGB; good enough for flat colors
  return length(a - b);
}

void main() {
  vec2 uv = vTexCoord;
  vec4 base = texture2D(tex0, uv);

  // --- Dot mask (same as before, pixel-stable)
  vec2 pixel = uv * u_resolution;
  vec2 dotCoordPx   = floor(pixel / dotSizePx) * dotSizePx;
  vec2 dotCenterPx  = dotCoordPx + dotSizePx * 0.5;

  vec2 d = (pixel - dotCenterPx) / (dotSizePx * 0.5);
  float dist = length(d);
  float mask = smoothstep(1.0, 0.0, dist); // 1 center, 0 outside

  // --- Exclude background-like pixels
  float cd = colorDist(base.rgb, u_skipColor);

  // exclude = 1 when pixel is close to skip color, 0 otherwise
  // This is a soft exclusion band to avoid halos.
  float exclude = 1.0 - smoothstep(u_skipTolerance * 0.75, u_skipTolerance, cd);

  // Apply dots only where NOT excluded
  float apply = mask * (1.0 - exclude);

  float darken = 1.0 - apply * dotStrength;
  vec3 outRgb = base.rgb * darken;

  gl_FragColor = vec4(outRgb, base.a);
}
`

let bloomFilterShader =  `
precision highp float;
varying vec2 vTexCoord;
uniform sampler2D tex0;
uniform vec2 canvasSize;
uniform float intensity;
uniform float glow;

void main() {
		vec2 tc = vTexCoord.st;

		// Sample the original color
		vec4 originalColor = texture2D(tex0, tc);

		// Calculate the dynamic texOffset based on the texture size
		vec2 texOffset = 1.0 / canvasSize;

		// Blur the image
		vec4 blurredColor = vec4(0.0);

		// Adjust glow value within a reasonable range
		float clampedGlow = clamp(glow, 0.0, 8.0);

		// Calculate the blur offset
		vec2 blurOffset = vec2(clampedGlow / canvasSize.x, 0.0);

		// Accumulate blurred colors
		for (float i = -8.0; i <= 8.0; i += 1.0) {
				vec2 offset = i * blurOffset;
				blurredColor += texture2D(tex0, vTexCoord.st + offset);
		}

		blurredColor /= 17.0;

		// Apply intensity to the blurred color
		blurredColor *= intensity;

		// Combine the original color and the blurred color using the Screen blending mode
		vec4 bloom = 1.0 - (1.0 - originalColor) * (1.0 - blurredColor);

		// Set the output color with the original vertex color
		gl_FragColor = bloom;
}
`


